import numpy as np
import torch
from src.vision_core.inference.preprocessor import  bgr_to_rgb,resize_image,normalize_image,to_tensor,preprocess_image



def test_bgr_to_rgb():
    image = np.array(
        [
            [[0, 0, 255]]
        ],
        dtype=np.uint8
    )

    result = bgr_to_rgb(image)

    expected = np.array(
        [
            [[255, 0, 0]]
        ],
        dtype=np.uint8
    )

    assert np.array_equal(result, expected)


def test_resize_image():
    image = np.zeros(
        (100, 200, 3),
        dtype=np.uint8
    )

    result = resize_image(
        image,
        size=(512, 512)
    )

    assert result.shape == (512, 512, 3)


def test_normalize_image():
    image = np.array(
        [
            [[0, 128, 255]]
        ],
        dtype=np.uint8
    )

    result = normalize_image(image)

    expected = np.array(
        [
            [[0.0, 128 / 255.0, 1.0]]
        ],
        dtype=np.float32
    )

    assert result.dtype == np.float32
    assert np.allclose(result, expected)


def test_to_tensor():
    image = np.zeros(
        (512, 512, 3),
        dtype=np.float32
    )

    result = to_tensor(image)

    assert isinstance(result, torch.Tensor)
    assert result.dtype == torch.float32
    assert result.shape == (3, 512, 512)


def test_preprocess_image_pipeline():
    image = np.zeros(
        (720, 1280, 3),
        dtype=np.uint8
    )

    result = preprocess_image(image)

    assert isinstance(result, torch.Tensor)
    assert result.dtype == torch.float32
    assert result.shape == (3, 512, 512)
    assert torch.all(result >= 0.0)
    assert torch.all(result <= 1.0)